import XCTest
import Security
@testable import Quip

/// GH #10: the tunnel pin check hashes a certificate's key the same way the
/// pin files were made (openssl over the SPKI DER), and the pin set covers
/// the chain trycloudflare.com serves.
final class CertPinningTests: XCTestCase {
    // Public CA certificates, DER. WE1 and GTS Root R4 (the GlobalSign
    // cross-signed copy) as trycloudflare.com served them on 2026-10-13;
    // ISRG Root X1 and GlobalSign Root CA from the macOS root store.
    private static let we1 = ""
    private static let gtsRootR4 = ""
    private static let isrgRootX1 = ""
    private static let globalSignRootCA = ""

    private func cert(_ base64: String) throws -> SecCertificate {
        let der = try XCTUnwrap(Data(base64Encoded: base64))
        return try XCTUnwrap(SecCertificateCreateWithData(nil, der as CFData))
    }

    /// Expected values are what `openssl x509 -pubkey -noout | openssl pkey
    /// -pubin -outform der | openssl dgst -sha256 -binary | base64` prints,
    /// one per key shape: EC P-256, EC P-384, RSA 4096, RSA 2048.
    func test_hashMatchesOpenSSLForEveryKeyShape() throws {
        typealias D = CloudflareCertificatePinningDelegate
        XCTAssertEqual(D.spkiSHA256(of: try cert(Self.we1)), "kIdp6NNEd8wsugYyyIYFsi1ylMCED3hZbSR8ZFsa/A4=")
        XCTAssertEqual(D.spkiSHA256(of: try cert(Self.gtsRootR4)), "mEflZT5enoR1FuXLgYYGqnVEoZvmf9c2bVBpiOjYQ0c=")
        XCTAssertEqual(D.spkiSHA256(of: try cert(Self.isrgRootX1)), "C5+lpZ7tcVwmwQIMcRtPbsQtWLABXhQzejna0wHFr8M=")
        XCTAssertEqual(D.spkiSHA256(of: try cert(Self.globalSignRootCA)), "K87oWBWM9UZfyddvDfoxL+8lpNyoUB2ptGtn0fv6G2Q=")
    }

    func test_todaysChainPassesThePinCheck() throws {
        let chain = [try cert(Self.we1), try cert(Self.gtsRootR4)]
        XCTAssertEqual(CloudflareCertificatePinningDelegate.firstPinnedPosition(
            in: chain, pins: CloudflareCertificatePinningDelegate.pinnedSPKIHashes), 0)
    }

    /// A chain with no pinned key is refused, and an unpinned certificate
    /// ahead of a pinned one does not stop the match.
    func test_onlyAPinnedKeyAnywhereInTheChainPasses() throws {
        let unpinned = try cert(Self.globalSignRootCA)
        XCTAssertNil(CloudflareCertificatePinningDelegate.firstPinnedPosition(
            in: [unpinned], pins: CloudflareCertificatePinningDelegate.pinnedSPKIHashes))
        XCTAssertEqual(CloudflareCertificatePinningDelegate.firstPinnedPosition(
            in: [unpinned, try cert(Self.isrgRootX1)],
            pins: CloudflareCertificatePinningDelegate.pinnedSPKIHashes), 1)
        XCTAssertNil(CloudflareCertificatePinningDelegate.firstPinnedPosition(
            in: [try cert(Self.we1)], pins: ["not-a-pin="]))
    }

    /// A pin rejection reaches the task only as NSURLErrorCancelled; the
    /// connection's error names the pin check instead.
    func test_aPinRejectionIsNamedNotReportedAsCancelled() {
        let cancelled = URLError(.cancelled)
        let named = WebSocketClient.connectFailureDetail(cancelled, pinRejectedHost: "abc.trycloudflare.com")
        XCTAssertTrue(named.contains("abc.trycloudflare.com"))
        XCTAssertTrue(named.contains("pin check failed"))
        XCTAssertEqual(WebSocketClient.connectFailureDetail(cancelled, pinRejectedHost: nil),
                       cancelled.localizedDescription)
    }

    func test_bundledPinsMatchTheHardcodedFallback() throws {
        let bundled = try XCTUnwrap(CloudflareCertificatePinningDelegate.loadFromBundle())
        XCTAssertEqual(bundled, CloudflareCertificatePinningDelegate.hardcodedFallback)
    }
}
